import sys
from math import isqrt

LIMIT = 10 ** 6

def get_primes():
    # 埃氏筛预处理纯净数
    is_prime = [True] * (LIMIT + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, isqrt(LIMIT) + 1):
        if is_prime[i]:
            for j in range(i * i, LIMIT + 1, i):
                is_prime[j] = False

    primes = []
    for i in range(2, LIMIT + 1):
        if is_prime[i]:
            primes.append(i)
    return primes

PRIMES = get_primes()

def check_prime(x):
    # 判断 x 是否为纯净数，这里 x 最大不超过 10^9
    if x < 2:
        return False
    for p in PRIMES:
        if p * p > x:
            break
        if x % p == 0:
            return False
    return True

def solve_one(n):
    ans = []
    x = n

    # 处理所有不超过 10^6 的纯净因子
    for p in PRIMES:
        if p * p > x:
            break

        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1

        # 如果 p 至少出现 2 次，则 p^2 是答案
        if cnt >= 2:
            ans.append(p * p)

    # 剩余部分可能是一个大纯净数的平方
    r = isqrt(x)
    if r * r == x and check_prime(r):
        ans.append(x)

    return ans

def main():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    res = []

    for i in range(1, t + 1):
        n = int(data[i])
        ans = solve_one(n)

        if ans:
            res.append(" ".join(map(str, ans)))
        else:
            res.append("-1")

    print("\n".join(res))

if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    static final int LIMIT = 1000000;
    static ArrayList<Integer> primes = new ArrayList<>();

    static void getPrimes() {
        // 埃氏筛预处理纯净数
        boolean[] isPrime = new boolean[LIMIT + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;

        for (int i = 2; i * i <= LIMIT; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= LIMIT; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        for (int i = 2; i <= LIMIT; i++) {
            if (isPrime[i]) {
                primes.add(i);
            }
        }
    }

    static boolean checkPrime(long x) {
        // 判断 x 是否为纯净数，这里 x 最大不超过 10^9
        if (x < 2) return false;

        for (int p : primes) {
            if ((long) p * p > x) break;
            if (x % p == 0) return false;
        }

        return true;
    }

    static ArrayList<Long> solveOne(long n) {
        ArrayList<Long> ans = new ArrayList<>();
        long x = n;

        // 处理所有不超过 10^6 的纯净因子
        for (int p : primes) {
            long pp = (long) p * p;
            if (pp > x) break;

            int cnt = 0;
            while (x % p == 0) {
                x /= p;
                cnt++;
            }

            // 如果 p 至少出现 2 次，则 p^2 是答案
            if (cnt >= 2) {
                ans.add(pp);
            }
        }

        // 剩余部分可能是一个大纯净数的平方
        long r = (long) Math.sqrt(x);
        while ((r + 1) * (r + 1) <= x) r++;
        while (r * r > x) r--;

        if (r * r == x && checkPrime(r)) {
            ans.add(x);
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        getPrimes();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();

        int T = Integer.parseInt(br.readLine().trim());

        for (int i = 0; i < T; i++) {
            long n = Long.parseLong(br.readLine().trim());
            ArrayList<Long> ans = solveOne(n);

            if (ans.isEmpty()) {
                out.append("-1");
            } else {
                for (int j = 0; j < ans.size(); j++) {
                    if (j > 0) out.append(' ');
                    out.append(ans.get(j));
                }
            }

            if (i + 1 < T) out.append('\n');
        }

        System.out.print(out.toString());
    }
}
