#include <bits/stdc++.h>
using namespace std;

const int LIMIT = 1000000;
vector<int> primes;

void get_primes() {
    // 埃氏筛预处理纯净数
    vector<bool> is_prime(LIMIT + 1, true);
    is_prime[0] = false;
    is_prime[1] = false;

    for (int i = 2; i * i <= LIMIT; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= LIMIT; j += i) {
                is_prime[j] = false;
            }
        }
    }

    for (int i = 2; i <= LIMIT; i++) {
        if (is_prime[i]) {
            primes.push_back(i);
        }
    }
}

bool check_prime(long long x) {
    // 判断 x 是否为纯净数，这里 x 最大不超过 10^9
    if (x < 2) return false;

    for (int p : primes) {
        if (1LL * p * p > x) break;
        if (x % p == 0) return false;
    }

    return true;
}

vector<long long> solve_one(long long n) {
    vector<long long> ans;
    long long x = n;

    // 处理所有不超过 10^6 的纯净因子
    for (int p : primes) {
        long long pp = 1LL * p * p;
        if (pp > x) break;

        int cnt = 0;
        while (x % p == 0) {
            x /= p;
            cnt++;
        }

        // 如果 p 至少出现 2 次，则 p^2 是答案
        if (cnt >= 2) {
            ans.push_back(pp);
        }
    }

    // 剩余部分可能是一个大纯净数的平方
    long long r = sqrt((long double)x);
    while ((r + 1) <= x / (r + 1)) r++;
    while (r > x / r) r--;

    if (r * r == x && check_prime(r)) {
        ans.push_back(x);
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    get_primes();

    int T;
    cin >> T;

    while (T--) {
        long long n;
        cin >> n;

        vector<long long> ans = solve_one(n);

        if (ans.empty()) {
            cout << -1;
        } else {
            for (int i = 0; i < (int)ans.size(); i++) {
                if (i) cout << ' ';
                cout << ans[i];
            }
        }

        if (T) cout << '\n';
    }

    return 0;
}
